        // High penalty for opening a new bin early, decreasing as the stream nears the end.
        score += 35.0 * (1.0 - progress.powf(0.5));

        // If other bins can fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Balance global bin usage by favoring bins that keep the mean_residual closer to 
    // the current bin's post_residual, promoting uniformity.
    score += (post_res - mean_residual).abs() * 0.2;

