        // If we have many open bins that could already fit the item, penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 150.0 * (fitting_bins_count as f64).sqrt();
        }
    } else {
        // 4. Global State Balancing: If this bin's residual is significantly lower than 
        // the mean_residual, it is a "tight" bin. We prioritize filling tight bins 
        // to keep the average bin fullness high.
