pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base Score: The post_residual represents wasted space if we don't fill it later.
    let mut score = post_residual as f64;

    // 2. Lookahead Penalty/Reward:
    // If the next item fits perfectly into the post_residual, we reward this bin heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: The closer post_residual is to next_item_size, the better.
            score -= (100.0 - (post_residual as f64 - next_item_size as f64)) * 1.5;
        } else {
            // Penalty: If we cannot fit the next item, we penalize the remaining space if it's "useless" (too small).
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // 3. Fitting Bin Constraint:
    // If this is the only bin that can fit the item, we heavily prioritize it to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // 4. New Bin Threshold:
    // If we are considering a new bin (bin_residual == bin_capacity), only pick it if
    // the average residual of current bins is very low, suggesting we should conserve 
    // capacity in existing bins rather than fragmenting.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 150.0; // Penalty for opening new bin if current bins have space
        } else {
            score += 50.0; // Baseline cost of opening a new bin
        }
    }

    // 5. Progression weighting:
    // As we near the end of the stream, we become more aggressive about filling bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in small residuals.
    // However, punish extremely small residuals (e.g., < 5) if they create "dead space"
    // that is unlikely to be filled by future items (if post_residual < 10, it's often a waste).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item could fit into the remaining space
    // of this bin, heavily prioritize this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global Density Awareness: If we have many open bins, we should be more
    // aggressive in filling the current one to reduce the open_bins_count.
    score += (open_bins_count as f64) * 2.0;

    // 4. New Bin Thresholding: If this is an empty bin (bin_residual == bin_capacity),
    // only consider opening it if the current placement options are very poor.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the existing bins are quite full.
        score += 60.0;

        // If we have few bins open, opening a new one is slightly less painful.
        score -= (open_bins_count as f64) * 5.0;
    }

    // 5. Dynamic Time Horizon: As we reach the end of the stream, prioritize
    // closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 50.0;
    }

    // 6. Fitting Constraint: If this is the ONLY bin that can fit the item, 
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}
